import{c as r,Q as o,j as t,m as a}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"Web Portal","description":"","frontmatter":{},"headers":[],"relativePath":"clients/web.md","filePath":"clients/web.md"}'),s={name:"clients/web.md"};function i(n,e,l,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="web-portal" tabindex="-1">Web Portal <a class="header-anchor" href="#web-portal" aria-label="Permalink to &quot;Web Portal&quot;">​</a></h1><p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.13 <strong>Since:</strong> 0.18.0</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The Phlix web portal runs in any modern browser — no software to install. Navigate to your server&#39;s web address, sign in with your Hub account or enter a direct server URL, and start streaming immediately. Works on Chrome, Firefox, Safari, and Edge.</p></div><h2 id="install-store-links" tabindex="-1">Install / Store Links <a class="header-anchor" href="#install-store-links" aria-label="Permalink to &quot;Install / Store Links&quot;">​</a></h2><ul><li><strong>No installation required</strong> — open the URL in your browser and start using it</li><li><strong>Supported browsers:</strong> Chrome 110+, Firefox 115+, Safari 16+, Edge 110+</li><li><strong>Mobile browsers:</strong> Fully functional but optimized for desktop</li></ul><p>Bookmark your server&#39;s web portal URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-server-domain.com/web</span></span></code></pre></div><p>Or for local access:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.100:32400/web</span></span></code></pre></div><h2 id="platform-specific-notes" tabindex="-1">Platform-Specific Notes <a class="header-anchor" href="#platform-specific-notes" aria-label="Permalink to &quot;Platform-Specific Notes&quot;">​</a></h2><ul><li>The web portal requires the server&#39;s web address to be reachable from your browser — either on the local network or via a Hub relay / reverse proxy.</li><li>Some browser extensions (ad blockers, privacy extensions) may interfere with playback. If playback does not start, try disabling extensions or using an incognito/private window.</li><li>For best playback performance, use a browser with hardware acceleration enabled (Chrome and Edge have this on by default).</li></ul><h2 id="setup-steps" tabindex="-1">Setup Steps <a class="header-anchor" href="#setup-steps" aria-label="Permalink to &quot;Setup Steps&quot;">​</a></h2><h3 id="open-the-web-portal" tabindex="-1">Open the Web Portal <a class="header-anchor" href="#open-the-web-portal" aria-label="Permalink to &quot;Open the Web Portal&quot;">​</a></h3><ol><li>Open your browser and navigate to your server&#39;s web URL.</li><li>You land on the Phlix login screen.</li></ol><h3 id="sign-in-with-hub-recommended-for-multi-server-users" tabindex="-1">Sign In With Hub (Recommended for Multi-Server Users) <a class="header-anchor" href="#sign-in-with-hub-recommended-for-multi-server-users" aria-label="Permalink to &quot;Sign In With Hub (Recommended for Multi-Server Users)&quot;">​</a></h3><ol><li>On the login screen, click <strong>Sign in with Hub</strong>.</li><li>Enter your Hub URL (e.g., <code>https://hub.phlix.example.com</code>) and press <strong>Continue</strong>.</li><li>Enter your Hub username and password, then click <strong>Sign In</strong>.</li><li>If your Hub account has multiple servers linked, a picker appears — select the server you want to access.</li><li>The portal loads your selected server&#39;s libraries.</li></ol><h3 id="sign-in-with-direct-server-url" tabindex="-1">Sign In With Direct Server URL <a class="header-anchor" href="#sign-in-with-direct-server-url" aria-label="Permalink to &quot;Sign In With Direct Server URL&quot;">​</a></h3><ol><li>On the login screen, click <strong>Connect Directly</strong>.</li><li>Enter your server&#39;s direct URL (e.g., <code>http://192.168.1.100:32400</code>) and press <strong>Connect</strong>.</li><li>Enter your server username and password.</li><li>The portal loads your server&#39;s libraries directly.</li></ol><h3 id="no-downloads-or-permissions" tabindex="-1">No Downloads or Permissions <a class="header-anchor" href="#no-downloads-or-permissions" aria-label="Permalink to &quot;No Downloads or Permissions&quot;">​</a></h3><p>The web portal uses standard browser APIs and requires no plugins, extensions, or special permissions.</p><h2 id="hub-connection" tabindex="-1">Hub Connection <a class="header-anchor" href="#hub-connection" aria-label="Permalink to &quot;Hub Connection&quot;">​</a></h2><ol><li>Click <strong>Sign in with Hub</strong> on the login screen.</li><li>Enter your Hub URL → authenticate → select a server.</li><li>The Hub relay provides remote access automatically — no router port forwarding or VPN required.</li><li>When signed in with Hub, switch between your Hub-linked servers from the user menu in the top-right corner.</li></ol><p>Hub login is the recommended way to access your server remotely because the Hub relay handles the connection without exposing your server directly to the internet.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="browser-not-supported" tabindex="-1">Browser not supported <a class="header-anchor" href="#browser-not-supported" aria-label="Permalink to &quot;Browser not supported&quot;">​</a></h3><p><strong>Symptom:</strong> The page looks broken or displays a banner &quot;Browser not supported.&quot;</p><p><strong>Fix:</strong> Your browser is outdated. Update to the latest version of Chrome, Firefox, Safari, or Edge. Internet Explorer is not supported — use Edge or another modern browser instead.</p><h3 id="websocket-blocked-by-network-proxy" tabindex="-1">WebSocket blocked by network proxy <a class="header-anchor" href="#websocket-blocked-by-network-proxy" aria-label="Permalink to &quot;WebSocket blocked by network proxy&quot;">​</a></h3><p><strong>Symptom:</strong> The page loads and you can see the library, but playback never starts and the console shows &quot;WebSocket connection error.&quot;</p><p><strong>Fix:</strong> Your network is blocking WebSocket connections (<code>ws://</code> or <code>wss://</code>). Try opening the portal from a different network. If you must use a restricted network, ask your network administrator to allow WebSocket traffic on port 443. As a workaround, use the Phlix mobile or desktop client.</p><h3 id="ssl-certificate-invalid-or-self-signed" tabindex="-1">SSL certificate invalid or self-signed <a class="header-anchor" href="#ssl-certificate-invalid-or-self-signed" aria-label="Permalink to &quot;SSL certificate invalid or self-signed&quot;">​</a></h3><p><strong>Symptom:</strong> The browser shows &quot;Your connection is not private&quot; and refuses to load the page.</p><p><strong>Fix:</strong> Your server is using a self-signed SSL certificate. For production, replace it with a properly signed certificate — <a href="https://letsencrypt.org" target="_blank" rel="noreferrer">Let&#39;s Encrypt</a> provides free automatic certificates. For local testing over HTTPS with a self-signed cert, type <code>thisisunsafe</code> on the Chrome warning page to proceed (Chrome only).</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./mobile.html">Mobile app</a> — iOS and Android</li><li><a href="./windows.html">Windows client</a> — desktop app with system tray and media key support</li><li><a href="./../first-run.html">First-run wizard</a> — complete server setup after your first login</li></ul>',35)])])}const b=r(s,[["render",i]]);export{u as __pageData,b as default};
